import React from 'react';

import { DownloadDataButton } from './DownloadDataButton.js';
import { ExploreButton } from './ExploreButton.js';
import { PanButton } from './PanButton.js';
import { ResetButton } from './ResetButton.js';
import { ZoomInOutButtons } from './ZoomInOutButtons.js';
import { Divider } from '../../../../typography/Divider.js';
import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { getA11yToolbarConfig } from '../../../core/functions/zoom.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { defaultToolbarPlacement } from '../../constants/defaults.js';
import { zIndicesHistogramAreas } from '../../constants/z-index.js';
import { useHistogramInteractions } from '../../hooks/useHistogramInteractions.js';
import { useHistogramToolbar } from '../../hooks/useHistogramToolbar.js';

type HistogramToolbarProps = {
  onMouseEnter: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
  onMouseLeave: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
};

export const HistogramToolbar = ({
  onMouseEnter,
  onMouseLeave,
}: HistogramToolbarProps) => {
  const { placement, collapsed, draggable, downloadData } =
    useHistogramToolbar();
  const { isInChartBounds } = useOverlaysEvents();
  const { zoom, zoomX, pan } = useHistogramInteractions();
  const anyInteractionEnabled =
    zoom?.enabled || zoomX?.enabled || pan?.enabled || downloadData?.enabled;

  const handleToggleMenu = (open: boolean): void => {
    !open && onMouseLeave();
  };

  return anyInteractionEnabled ? (
    <ChartToolbarRenderer
      visible={isInChartBounds}
      placement={placement || defaultToolbarPlacement}
      collapsed={collapsed}
      draggable={draggable}
      initialA11yState={getA11yToolbarConfig({
        zoomX,
        pan,
        zoom,
        download: downloadData,
      })}
      zIndex={zIndicesHistogramAreas.toolbar}
      onToggleMenu={handleToggleMenu}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <ExploreButton />
      <PanButton />
      <Divider orientation="vertical" as="hr" />
      <ZoomInOutButtons />
      <ResetButton />
      <Divider orientation="vertical" as="hr" />
      <DownloadDataButton />
    </ChartToolbarRenderer>
  ) : null;
};
